using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // --- Stock Level Tests ---

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        int level = _tracker.GetStockLevel("UNKNOWN-SKU");

        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void AddStock_NewSku_SetsStockLevel()
    {
        _tracker.AddStock("SKU-001", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-001", 30);
        _tracker.AddStock("SKU-001", 20);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_NegativeQuantity_ThrowsArgumentException()
    {
        _tracker.AddStock("SKU-001", -5);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_ZeroQuantity_ThrowsArgumentException()
    {
        _tracker.AddStock("SKU-001", 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void AddStock_NullSku_ThrowsArgumentNullException()
    {
        _tracker.AddStock(null!, 10);
    }

    // --- Reorder Alert Tests ---

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-001", 100);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtZero_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("SKU-EMPTY"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-001", 1);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    // --- Warehouse Transfer Tests ---
    // These tests anticipate a Transfer(fromSku, toSku, quantity) method.
    // Uncomment once the method is implemented.

